Home.css:
body{margin:0}
a{color:#A0021F}a:hover{color:#7E0118}
.dhu-weave{background-color:#A0021F;background-image:url(/generated/dhu-weave-red-fade.png);background-repeat:no-repeat;background-size:640px auto;background-position:right -120px center}
.dhu-band{background-color:#A0021F;background-image:url(/generated/dhu-weave-red-fade.png);background-repeat:repeat-x;background-size:480px auto;background-position:left -40px center}
.fm-navlinks{scrollbar-width:none}.fm-navlinks::-webkit-scrollbar{display:none}
@media (max-width:1279px){.fm-header-row{gap:24px!important}.fm-slot{display:none!important}.fm-hero-grid{grid-template-columns:232px minmax(0,1fr)!important}.fm-hero-aside{grid-column:1 / -1;flex-direction:row!important;align-items:flex-start;margin-top:0!important}.fm-hero-aside>*{flex:1 1 0}}
@media (max-width:1100px){.fm-freeship{display:none!important}.fm-navgap{gap:20px!important}.fm-hot{display:none!important}}

/* R03: editorial food photograph and live product picks. */
.fm-market{margin-top:16px;min-width:0;min-height:440px;border:1px solid #E3E8E5;border-radius:10px;overflow:hidden;background:#FFF;display:grid;grid-template-rows:minmax(318px,1fr) auto}
.fm-market-scene{isolation:isolate;position:relative;overflow:hidden;background:#18352A;display:flex;align-items:center;min-height:318px}
.fm-market-photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:58% center;z-index:-2}
.fm-market-scene:after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(13,35,27,.75) 0%,rgba(13,35,27,.48) 34%,rgba(13,35,27,.03) 68%)}
.fm-market-copy{position:relative;padding:30px 30px 28px;max-width:64%;box-sizing:border-box;color:#FFF}
.fm-market-kicker{display:flex;align-items:center;gap:9px;margin:0 0 17px;font-size:11px;line-height:1.5;font-weight:600;letter-spacing:.13em;color:#DFE9DC}
.fm-market-kicker:before{content:"";width:21px;height:1px;background:#C6D5AD;flex:none}
.fm-market-title{margin:0;font-size:clamp(30px,2.75vw,40px);font-weight:700;line-height:1.23;letter-spacing:-.035em;white-space:nowrap}
.fm-market-title span{color:#D8E9A5}
.fm-market-description{margin:17px 0 22px;color:#E0E8DE;font-size:12px;line-height:1.85}
.fm-market-cta{display:inline-flex;align-items:center;gap:24px;min-height:40px;padding:0 16px;border:1px solid #FFF;border-radius:5px;background:#FFF;color:#183A2D!important;font-size:13px;font-weight:700;text-decoration:none;transition:background .18s ease,transform .18s ease}
.fm-market-cta svg{width:16px;height:16px}.fm-market-cta:hover{background:#EDF3E6;transform:translateY(-1px)}
.fm-market-links{display:flex;gap:16px;margin-top:17px}.fm-market-links a{color:#E4ECDD;font-size:11px;line-height:1.6;text-decoration:none;border-bottom:1px solid rgba(228,236,221,.45)}.fm-market-links a:hover{color:#FFF;border-color:#FFF}
.fm-market-picks{padding:13px 12px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;background:#FFF}
.fm-market-pick{display:flex;align-items:center;gap:9px;min-width:0;padding:6px 10px;color:#1B1F24;text-decoration:none;border-right:1px solid #EBEFEC;border-radius:3px;transition:background .18s ease}.fm-market-pick:last-child{border-right:0}.fm-market-pick[hidden]{display:none}.fm-market-pick:hover{background:#F5F7F3}
.fm-market-pick img{width:54px;height:58px;flex:none;object-fit:contain;border-radius:5px;background:#F8F9F7}
.fm-market-pick-copy{display:flex;flex-direction:column;gap:3px;min-width:0}.fm-market-pick-name{font-size:12px;font-weight:600;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fm-market-pick-unit{font-size:10px;line-height:1.5;color:#737A74;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fm-market-pick-price{font-size:15px;line-height:1.45;font-weight:700;font-variant-numeric:tabular-nums;color:#A0021F}
.fm-market a:focus-visible{outline:2px solid #9DB47F;outline-offset:3px}
@media (min-width:1280px) and (max-width:1350px){.fm-market-copy{padding-left:24px}.fm-market-title{font-size:34px}.fm-market-pick{padding:6px;gap:6px}.fm-market-pick img{width:44px}}
@media (max-width:1279px){.fm-market{min-height:440px}.fm-market-copy{padding:30px 36px}.fm-market-photo{object-position:62% center}.fm-market-title{font-size:40px}}
@media (max-width:760px){.fm-market-copy{padding:24px;max-width:75%}.fm-market-title{font-size:30px}.fm-market-description{font-size:11px}.fm-market-picks{padding:8px 4px}.fm-market-pick{flex-direction:column;align-items:flex-start;padding:7px}.fm-market-pick img{width:48px;height:44px}}
@media (prefers-reduced-motion:reduce){.fm-market-cta,.fm-market-pick{transition:none}.fm-market-cta:hover{transform:none}}

